def average(numbers):
    if not numbers:
        return None  # no scores recorded -- there is no meaningful average
    return sum(numbers) / len(numbers)

def summarize_scores(scores_by_student):
    results = {}
    for student, scores in scores_by_student.items():
        results[student] = average(scores)
    return results

print(summarize_scores({"Amy": [90, 85, 92], "Ben": []}))
# {'Amy': 89.0, 'Ben': None}
